renderVectorPoly = {
  const svg = d3.select("#vector-poly-container").append("svg")
    .attr("width", size).attr("height", size).style("border", "1px solid #eee");

  const center = size / 2;
  const radius = 72;
  const sides = 6; // Hexagon

  const vertices = d3.range(sides).map(i =&gt; {
    const angle = (i / sides) * Math.PI * 2 - Math.PI / 2;
    return [center + radius * Math.cos(angle), center + radius * Math.sin(angle)];
  });

  const lineGenerator = d3.line().curve(d3.curveLinearClosed);

  svg.append("path")
    .attr("d", lineGenerator(vertices))
    .attr("fill", themeColor);

  svg.selectAll("circle")
    .data(vertices).enter().append("circle")
    .attr("cx", d =&gt; d[0]).attr("cy", d =&gt; d[1]).attr("r", 5)
    .attr("fill", "white").attr("stroke", "#333");
}

renderRasterPoly = {
  const svg = d3.select("#raster-poly-container").append("svg")
    .attr("width", size).attr("height", size).style("border", "1px solid #eee");

  for (let i = 0; i &lt; res; i++) {
    for (let j = 0; j &lt; res; j++) {
      const x = (i - res/2) / (res/2.5);
      const y = (j - res/2) / (res/2.5);

      const inHex = (Math.abs(x) &lt; 0.8 && Math.abs(x*0.5 + y*0.8) &lt; 0.8 && Math.abs(x*0.5 - y*0.8) &lt; 0.8);

      svg.append("rect")
        .attr("x", i * cellSize).attr("y", j * cellSize)
        .attr("width", cellSize).attr("height", cellSize)
        .attr("fill", inHex ? themeColor : "#f2f2f2")
        .attr("stroke", "#fff").attr("stroke-width", 2);
    }
  }
}

Vector data model
Three basic vector types exist: points, lines, and polygons. Points are the fundamental unit of the vector data model. They make up everything! In the health context, points often map to the location of facilities, points of interest, or homes. Lines are simply multiple points stitched together with straight line segments. This allows us to represent things like roads, rivers, or even the movement of people. Polygons extend the concept of lines by stitching together points with line segments to form an enclosed area.

