    .attr("font-weight", "bold")
    .attr("fill", "#333")
    .text(d =&gt; d.label);

  g.filter(d =&gt; d.type === "polygon")
    .append("polygon")
    .attr("points", basePoints.map(p =&gt; p.join(",")).join(" "))
    .attr("fill", themeColor)
    .attr("fill-opacity", 0.2)
    .attr("stroke", "#333")
    .attr("stroke-width", 2);

  g.filter(d =&gt; d.type !== "point")
    .append("path")
    .attr("d", d =&gt; {
      const lineGen = d3.line();
      return d.type === "polygon" 
        ? lineGen([...basePoints, basePoints[0]]) 
        : lineGen(basePoints);
    })
    .attr("fill", "none")
    .attr("stroke", "#333")
    .attr("stroke-width", 2);

  g.selectAll("circle")
    .data(basePoints)
    .join("circle")
    .attr("cx", d =&gt; d[0])
    .attr("cy", d =&gt; d[1])
    .attr("r", 6)
    .attr("fill", themeColor)
    .attr("stroke", "#fff")
    .attr("stroke-width", 1.5);

  return svg.node();
}






